import { chacha20poly1305 as chacha20poly1305noble } from './chacha.native.mjs'
import { assert, assertUint8 } from './utils/assertUint8.mjs'
import { createCipherApi, directMethods } from './utils/cipher.mjs'
import { getCiphers, createCipheriv, createDecipheriv } from 'node:crypto'

const cipher = 'chacha20-poly1305'

async function chacha20poly1305node(key, usage) {
  assertUint8(key, 32, 'key')
  return createCipherApi(usage, {
    async encrypt(data, nonce, additionalData) {
      assertUint8(nonce, 12, 'nonce')
      const c = createCipheriv(cipher, key, nonce)
      if (additionalData && additionalData.length !== 0) c.setAAD(additionalData)
      return Buffer.concat([c.update(data), c.final(), c.getAuthTag()])
    },
    async decrypt(data, nonce, additionalData) {
      assertUint8(nonce, 12, 'nonce')
      assert(data.length >= 16, 'encrypted data must be at least 16 bytes')
      const ciphertext = data.subarray(0, -16)
      const authTag = data.subarray(-16)
      const d = createDecipheriv(cipher, key, nonce)
      if (additionalData && additionalData.length !== 0) d.setAAD(additionalData)
      d.setAuthTag(authTag)
      return Buffer.concat([d.update(ciphertext), d.final()])
    },
  })
}

// Falls back to noble
export const chacha20poly1305 = getCiphers().includes(cipher)
  ? chacha20poly1305node
  : chacha20poly1305noble

const { encrypt: encryptChacha20poly1305, decrypt: decryptChacha20poly1305 } =
  directMethods(chacha20poly1305)

export { encryptChacha20poly1305, decryptChacha20poly1305 }
